draw(C--D);

dot(Label("$A$",align=SW),A);

dot(Label("$B$",align=SE),B);

dot(Label("$C$",align=S),C);

dot(Label("$D$",align=S),D);

for(int i = 0; i < 5; ++i){

draw(C--(C + 5*dir(72*i)));

}

label("Top View",(25,-2),3*S);
